import{_ as i,l as s,o as e,c as l,v as n,p as o,x as t,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"哈密顿与 TSP 精确解","description":"","frontmatter":{"title":"哈密顿与 TSP 精确解","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hamiltonian-tsp-exact.md","filePath":"cs/hamiltonian-tsp-exact.md","lastUpdated":1789023840000}'),m={name:"cs/hamiltonian-tsp-exact.md"};function h(P,a,u,S,_,T){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=n('<h1 id="哈密顿与-tsp-精确解" tabindex="-1">哈密顿与 TSP 精确解 <a class="header-anchor" href="#哈密顿与-tsp-精确解" aria-label="Permalink to &quot;哈密顿与 TSP 精确解&quot;">​</a></h1><div class="epigraph"><p>点各走一次是 NPC；精确求解靠子集 DP：在已访问集合与当前点上转移，Held–Karp 把 $n!$ 降到 $O(2^n n^2)$。</p><footer>—— 据 Held and Karp, A Dynamic Programming Approach to Sequencing Problems, 1962；Bellman, Dynamic Programming Treatment of the Travelling Salesman Problem, 1962；CLRS 第 34、35 章整理</footer></div><p>上一课<a href="/cs/euler-circuit">欧拉回路</a>在边上线性可解。本课换到<strong>点各一次</strong>：哈密顿路/回路，以及旅行商（TSP）的精确最优。不重写欧拉的度条件。缺口是：为何难，以及精确算法还能做什么——不是近似（Christofides 在后课近似单元）。主干<a href="/cs/npc-canonical">NPC 典型问题</a>已点名哈密顿；本课把指数 DP 写清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>哈密顿回路：简单圈过每个点。无向/有向都 NPC（Karps 清单）。TSP：完全图（或补 \\(\\infty\\)）上求最短哈密顿回路。度量 TSP 仍 NPC，但有近似；本课要的是<strong>精确值</strong>。</p><p>枚举排列 \\(O(n!)\\)。Held–Karp / Bellman：\\(dp[S][v]=\\) 从定点 \\(s\\) 出发、走过集合 \\(S\\)、停在 \\(v\\) 的最短路长，其中 \\(s\\in S\\)、\\(v\\in S\\)。转移：\\(dp[S][v]=\\min_{u\\in S\\setminus\\{v\\}} dp[S\\setminus\\{v\\}][u]+w(u,v)\\)。状态 \\(O(2^n n)\\)，转移 \\(O(n)\\)，总 \\(O(2^n n^2)\\)。回路再从各 \\(v\\) 加 \\(w(v,s)\\) 取最小。</p><p>缺口是这张表，不是再证 NPC。</p><h3 id="指数仍可能比-可用" tabindex="-1">指数仍可能比 \\(n!\\) 可用 <a class="header-anchor" href="#指数仍可能比-可用" aria-label="Permalink to &quot;指数仍可能比 $n!$ 可用&quot;">​</a></h3><p>\\(n\\le 20\\) 量级常靠这张 DP；\\(n=40\\) 要剪枝、分支定界或专门求解器。本课不把求解器当算法定义。不要对一般图声称多项式哈密顿——除非 P=NP。</p><p><span class="marginnote">Held–Karp 1962 与 Bellman 1962 独立给出 TSP 的子集 DP。Karp 1972 把哈密顿列入 21 题。后课 LCA 离开难解回路，进入树上的查询。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定点 \\(s\\)。初始化 \\(dp[\\{s\\}][s]=0\\)。按 \\(|S|\\) 升序填表。求回路时枚举回到 \\(s\\) 的边。可记录前驱还原路径。空间 \\(O(2^n n)\\) 可用滚动或哈希存可达子集，本课记标准界。</p>',12)),(e(),o(c,null,{default:t(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HAM%5B%22%E5%93%88%E5%AF%86%E9%A1%BF%20%2F%20TSP%22%5D%20--%3E%20DP%5B%22dp%5BS%5D%5Bv%5D%20%E5%AD%90%E9%9B%86%2B%E7%BB%88%E7%82%B9%22%5D%0A%20%20DP%20--%3E%20OPT%5B%22O(2%5En%20n%5E2)%20%E7%B2%BE%E7%A1%AE%22%5D%0A%20%20HAM%20--%3E%20NPC%5B%22%E5%88%A4%E5%AE%9A%E7%89%88%20NPC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>有向、无向同一骨架，边权可只取存在的边。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最优子结构：最短 \\((s,S,v)\\) 路径的倒数第二点 \\(u\\)，前缀必须是最短 \\((s,S\\setminus\\{v\\},u)\\)——否则替换。这与<a href="/cs/dynamic-programming">动态规划</a>的最优子结构同型，状态是子集不是前缀。欧拉没有这张表：边的状态可用度数局部检查。</p><p>分支定界用下界（MST、分配问题）剪掉排列树，最坏仍指数；与 DP 互补，本课点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写度量 3/2 近似，不写 Christofides。不引入代数方法（Koutsoupias 等之外的 Contour/Held–Karp 变体可点到：有随机多项式空间算法，不展开）。后课默认：哈密顿/TSP 精确 = 子集 DP 或指数搜索；判定 NPC。下一课树上最近公共祖先，图变树、查询变倍增。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>点各一次：判定 NPC；精确 TSP 用 Held–Karp。</li><li>\\(O(2^n n^2)\\) 不是多项式，但远好于 \\(n!\\)。</li><li>欧拉在边、哈密顿在点，不要混。</li><li>出处：Held and Karp, 1962；Bellman, 1962。</li></ul>',8))])}const A=i(m,[["render",h]]);export{E as __pageData,A as default};
